package org.sleepwell.app;
import android.content.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
/** Independent private diary. Main record schema/backups never receive journal text. */
final class DiaryStore extends SQLiteOpenHelper {
 interface Factory{DiaryStore open(Context context);}static Factory factory=DiaryStore::new;static DiaryStore open(Context c){return factory.open(c);}
 DiaryStore(Context c){this(c,"sleepwell-diary.db");}DiaryStore(Context c,String name){super(c,name,null,1);}
 public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE entries(id TEXT PRIMARY KEY,created INTEGER NOT NULL,updated INTEGER NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,origin TEXT NOT NULL,owner TEXT UNIQUE)");}public void onUpgrade(SQLiteDatabase db,int old,int version){throw new SQLiteException("Unsupported diary version");}
 static final class Entry {final String id,title,text,origin;final long created,updated;Entry(String id,long created,long updated,String title,String text,String origin){this.id=id;this.created=created;this.updated=updated;this.title=title;this.text=text;this.origin=origin;}}
 List<Entry> entries(){return entries(200,0);}
 int count(){try(android.database.Cursor cursor=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM entries",null)){cursor.moveToFirst();return cursor.getInt(0);}}
 List<Entry> entries(int limit,int offset){List<Entry> result=new ArrayList<>();try(android.database.Cursor cursor=getReadableDatabase().rawQuery("SELECT id,created,updated,title,body,origin FROM entries ORDER BY created DESC,id LIMIT ? OFFSET ?",new String[]{""+Math.max(1,Math.min(200,limit)),""+Math.max(0,offset)})){while(cursor.moveToNext())result.add(new Entry(cursor.getString(0),cursor.getLong(1),cursor.getLong(2),cursor.getString(3),cursor.getString(4),cursor.getString(5)));}return List.copyOf(result);}
 static void validate(String title,String text){if(title==null||title.length()>80||text==null||text.isBlank()||text.codePointCount(0,text.length())>JournalRule.MAX)throw new IllegalArgumentException("Add an entry up to 5,000 characters and a title up to 80 characters.");}
 Entry byOwner(String owner){try(android.database.Cursor cursor=getReadableDatabase().rawQuery("SELECT id,created,updated,title,body,origin FROM entries WHERE owner=?",new String[]{owner})){return cursor.moveToFirst()?new Entry(cursor.getString(0),cursor.getLong(1),cursor.getLong(2),cursor.getString(3),cursor.getString(4),cursor.getString(5)):null;}}
 String challenge(String owner,String text,int minimum,long now,java.util.function.BooleanSupplier current){if(owner==null||owner.isBlank()||owner.length()>128)throw new IllegalArgumentException("Missing journal owner");String problem=JournalRule.problem(text,minimum);if(!problem.isEmpty())throw new IllegalArgumentException(problem);SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{if(!current.getAsBoolean())throw new IllegalStateException("This journal challenge is no longer current.");Entry existing=byOwner(owner);if(existing!=null){db.setTransactionSuccessful();return existing.id;}String id=UUID.randomUUID().toString();insert(id,now,"Morning journal",text,"challenge",owner);if(!current.getAsBoolean())throw new IllegalStateException("The alarm changed before the entry was saved.");db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 String save(String id,long expected,String title,String text,long now){validate(title,text);SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{if(id==null||id.isEmpty()){id=UUID.randomUUID().toString();insert(id,now,title,text,"user",null);}else if(expected==0){try(android.database.Cursor prior=db.rawQuery("SELECT created,updated,title,body,origin FROM entries WHERE id=?",new String[]{id})){if(prior.moveToFirst()){if(prior.getLong(0)!=prior.getLong(1)||!prior.getString(2).equals(title)||!prior.getString(3).equals(text)||!prior.getString(4).equals("user"))throw new IllegalStateException("This diary request changed. Reopen the saved entry.");}else insert(id,now,title,text,"user",null);}}else{ContentValues values=new ContentValues();values.put("title",title);values.put("body",text);values.put("updated",Math.max(now,expected+1));if(db.update("entries",values,"id=? AND updated=?",new String[]{id,""+expected})!=1)throw new IllegalStateException("This diary entry changed. Reopen it before saving.");}db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 void insert(String id,long now,String title,String text,String origin,String owner){validate(title,text);ContentValues values=new ContentValues();values.put("id",id);values.put("created",now);values.put("updated",now);values.put("title",title);values.put("body",text);values.put("origin",origin);if(owner==null)values.putNull("owner");else values.put("owner",owner);getWritableDatabase().insertOrThrow("entries",null,values);}
 void delete(String id,long expected){if(getWritableDatabase().delete("entries","id=? AND updated=?",new String[]{id,""+expected})!=1)throw new IllegalStateException("This diary entry changed. Reopen it first.");}
 byte[] export()throws Exception{java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();write(out,"{\"diary_format\":1,\"entries\":[");boolean first=true;try(android.database.Cursor cursor=getReadableDatabase().rawQuery("SELECT id,created,updated,title,body,origin FROM entries ORDER BY created DESC,id",null)){while(cursor.moveToNext()){JSONObject row=new JSONObject().put("id",cursor.getString(0)).put("created",cursor.getLong(1)).put("updated",cursor.getLong(2)).put("title",cursor.getString(3)).put("text",cursor.getString(4)).put("origin",cursor.getString(5));write(out,(first?"":",")+row);first=false;}}write(out,"]}");return out.toByteArray();}
 static void write(java.io.ByteArrayOutputStream out,String value)throws java.io.IOException{byte[] bytes=value.getBytes(java.nio.charset.StandardCharsets.UTF_8);if(out.size()+bytes.length>4*1024*1024)throw new IllegalStateException("This diary exceeds the 4 MiB export limit.");out.write(bytes);}

}
